CREATE TRIGGER render_immutable BEFORE UPDATE ON renders WHEN OLD.status='SUCCEEDED' OR NEW.id<>OLD.id OR NEW.project_id<>OLD.project_id OR NEW.job_id<>OLD.job_id OR NEW.manifest_id<>OLD.manifest_id OR NEW.manifest_hash<>OLD.manifest_hash OR NEW.manifest_json<>OLD.manifest_json OR NEW.preset<>OLD.preset OR NEW.version_no<>OLD.version_no OR NEW.created_at<>OLD.created_at BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RENDER'); END;
